package com.primehr.rsp.selection.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.shared.exception.*;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="rsp_offer_response") public class OfferResponse extends RspAuditedEntity{public enum Status{PENDING,ACCEPTED,DECLINED,EXPIRED}@Column(name="selection_case_id",nullable=false,length=36)private String selectionCaseId;@Column(name="application_id",nullable=false,length=36)private String applicationId;@Column(name="applicant_id",nullable=false,length=36)private String applicantId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="response_deadline",nullable=false)private Instant responseDeadline;@Column(name="idempotency_key",length=100)private String idempotencyKey;@Column(name="responded_at")private Instant respondedAt;@Column(name="applicant_comment",length=1000)private String applicantComment;protected OfferResponse(){}public OfferResponse(String agency,String selection,String application,String applicant,Instant deadline){super(agency);selectionCaseId=requiredText(selection,"selectionCaseId");applicationId=requiredText(application,"applicationId");applicantId=requiredText(applicant,"applicantId");responseDeadline=java.util.Objects.requireNonNull(deadline);status=Status.PENDING;}public void respond(Status decision,String key,String comment,Instant at){if(decision!=Status.ACCEPTED&&decision!=Status.DECLINED)throw new IllegalArgumentException("Offer response must be ACCEPTED or DECLINED");String normalized=requiredText(key,"idempotencyKey");if(status!=Status.PENDING){if(idempotencyKey!=null&&idempotencyKey.equals(normalized)&&status==decision)return;throw new ApplicationConflictException("The offer already has a different final response");}if(!at.isBefore(responseDeadline))throw new ApplicationConflictException("The offer response deadline has expired");status=decision;idempotencyKey=normalized;applicantComment=optionalText(comment);respondedAt=at;}public boolean expire(Instant at){if(status==Status.PENDING&&!at.isBefore(responseDeadline)){status=Status.EXPIRED;return true;}return false;}public String getSelectionCaseId(){return selectionCaseId;}public String getApplicationId(){return applicationId;}public String getApplicantId(){return applicantId;}public Status getStatus(){return status;}public Instant getResponseDeadline(){return responseDeadline;}public String getIdempotencyKey(){return idempotencyKey;}public Instant getRespondedAt(){return respondedAt;}public String getApplicantComment(){return applicantComment;}}
